css:
.caribia-sim-container {
    padding: 24px;
    background: linear-gradient(180deg, #fdf6e3 0%, #f5e7c8 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2a3f3f;
}

.caribia-sim-header {
    background: linear-gradient(135deg, #0d6e6e 0%, #1a8d8d 50%, #2a3f3f 100%);
    color: #fdf6e3;
    border-radius: 18px;
    padding: 36px 40px;
    margin-bottom: 24px;
    box-shadow: 0 14px 36px rgba(13,110,110,0.28);
    position: relative;
    overflow: hidden;
}

.caribia-sim-header::after {
    content: '';
    position: absolute;
    top: -40px;
    right: -40px;
    width: 240px;
    height: 240px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(201,164,73,0.35) 0%, rgba(201,164,73,0) 70%);
}

.caribia-sim-brandline {
    color: #c9a449;
    font-size: 0.78rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 12px;
    font-weight: 600;
    position: relative;
    z-index: 1;
}

.caribia-sim-header h1 {
    color: #fdf6e3;
    font-size: 2.1rem;
    font-weight: 700;
    margin: 0 0 10px 0;
    letter-spacing: -0.01em;
    position: relative;
    z-index: 1;
}

.caribia-sim-subtitle {
    color: #d6e6e6;
    font-size: 0.98rem;
    font-style: italic;
    max-width: 720px;
    line-height: 1.4;
    position: relative;
    z-index: 1;
}

.caribia-sim-period-bar {
    background: #ffffff;
    border-left: 5px solid #c9a449;
    border-radius: 8px;
    padding: 16px 24px;
    margin-bottom: 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 3px 12px rgba(0,0,0,0.06);
    flex-wrap: wrap;
    gap: 12px;
}

.caribia-sim-period-left {
    display: flex;
    align-items: baseline;
    gap: 6px;
}

.caribia-sim-round-label,
.caribia-sim-round-of {
    color: #6b7e7e;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.caribia-sim-round-num {
    color: #0d6e6e;
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 4px;
}

.caribia-sim-period-right {
    color: #2a3f3f;
    font-size: 1.05rem;
    font-weight: 600;
    text-align: right;
}

.caribia-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}

.caribia-sim-kpi-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 20px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.07);
    border-top: 4px solid #c9a449;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.caribia-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 24px rgba(0,0,0,0.1);
}

.caribia-sim-kpi-revenue { border-top-color: #0d6e6e; }
.caribia-sim-kpi-ebitda { border-top-color: #c9a449; }
.caribia-sim-kpi-capex { border-top-color: #b85c38; }
.caribia-sim-kpi-turnover { border-top-color: #6b7e7e; }

.caribia-sim-kpi-label {
    color: #6b7e7e;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}

.caribia-sim-kpi-value {
    color: #0d6e6e;
    font-size: 2.2rem;
    font-weight: 700;
    line-height: 1.1;
    margin-bottom: 6px;
}

.caribia-sim-kpi-target {
    color: #8a9999;
    font-size: 0.78rem;
    font-style: italic;
}

.caribia-sim-briefing {
    background: linear-gradient(135deg, #fdf6e3 0%, #f5e7c8 100%);
    border: 1px solid #d4b878;
    border-left: 5px solid #c9a449;
    border-radius: 12px;
    padding: 24px 28px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(201,164,73,0.12);
}

.caribia-sim-briefing-tag {
    color: #b85c38;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    margin-bottom: 10px;
}

.caribia-sim-briefing h3 {
    color: #2a3f3f;
    font-size: 1.3rem;
    font-weight: 700;
    margin: 0 0 12px 0;
}

.caribia-sim-briefing-text {
    color: #2a3f3f;
    font-size: 0.94rem;
    line-height: 1.55;
}

.caribia-sim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 28px 30px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.07);
    border-top: 3px solid #0d6e6e;
}

.caribia-sim-controls h3 {
    color: #0d6e6e;
    font-size: 1.15rem;
    font-weight: 700;
    margin: 0 0 20px 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #f5e7c8;
    padding-bottom: 10px;
}

.caribia-sim-round-panel {
    animation: caribiaFadeIn 0.3s ease;
}

@keyframes caribiaFadeIn {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
}

.caribia-sim-control-row {
    margin-bottom: 18px;
}

.caribia-sim-control-row label {
    display: block;
    color: #2a3f3f;
    font-size: 0.92rem;
    font-weight: 600;
    margin-bottom: 8px;
}

.caribia-sim-controls input[type="number"],
.caribia-sim-controls select {
    background: #ffffff;
    border: 1.5px solid #d4b878;
    color: #2a3f3f;
    border-radius: 6px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.caribia-sim-controls input[type="number"]:focus,
.caribia-sim-controls select:focus {
    outline: none;
    border-color: #0d6e6e;
    box-shadow: 0 0 0 3px rgba(13,110,110,0.12);
}

.caribia-sim-controls select option {
    background: #ffffff;
    color: #2a3f3f;
}

.caribia-sim-hint-box {
    background: rgba(13,110,110,0.06);
    border-left: 3px solid #0d6e6e;
    color: #2a3f3f;
    padding: 12px 16px;
    border-radius: 4px;
    font-size: 0.85rem;
    line-height: 1.5;
    margin-bottom: 18px;
    font-style: italic;
}

.caribia-sim-capex-list,
.caribia-sim-retention-list {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
    margin-top: 6px;
}

.caribia-sim-capex-item,
.caribia-sim-retention-item {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 10px 12px;
    background: #fdf6e3;
    border: 1px solid #e8d8b0;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.2s ease, border-color 0.2s ease;
    font-size: 0.86rem;
    font-weight: 500;
    color: #2a3f3f;
    margin-bottom: 0;
}

.caribia-sim-capex-item:hover,
.caribia-sim-retention-item:hover {
    background: #f5e7c8;
    border-color: #c9a449;
}

.caribia-sim-capex-item input[type="checkbox"],
.caribia-sim-retention-item input[type="checkbox"] {
    margin-top: 2px;
    accent-color: #0d6e6e;
    flex-shrink: 0;
}

.caribia-sim-capex-mandatory {
    background: rgba(13,110,110,0.08);
    border-color: #0d6e6e;
    color: #0d6e6e;
    font-weight: 600;
}

.caribia-sim-capex-running {
    margin-top: 12px;
    padding: 10px 14px;
    background: #2a3f3f;
    color: #c9a449;
    border-radius: 6px;
    font-weight: 700;
    font-size: 0.92rem;
    text-align: right;
    letter-spacing: 0.04em;
}

.caribia-sim-button-row {
    margin-top: 24px;
    display: flex;
    gap: 12px;
    align-items: center;
}

.caribia-sim-submit-btn {
    background: #0d6e6e;
    border: none;
    color: #fdf6e3;
    padding: 12px 32px;
    border-radius: 8px;
    font-weight: 700;
    font-size: 0.98rem;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    cursor: pointer;
    transition: background 0.2s ease, transform 0.15s ease, box-shadow 0.2s ease;
    box-shadow: 0 4px 12px rgba(13,110,110,0.25);
}

.caribia-sim-submit-btn:hover {
    background: #1a8d8d;
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(13,110,110,0.32);
}

.caribia-sim-undo-btn {
    background: transparent;
    border: 1.5px solid #6b7e7e;
    color: #6b7e7e;
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 0.85rem;
    cursor: pointer;
    transition: background 0.2s ease, color 0.2s ease;
}

.caribia-sim-undo-btn:hover {
    background: #6b7e7e;
    color: #fdf6e3;
}

.caribia-sim-history {
    background: #ffffff;
    border-radius: 14px;
    padding: 24px 28px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.07);
    border-top: 3px solid #c9a449;
    overflow-x: auto;
}

.caribia-sim-history h3 {
    color: #0d6e6e;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.caribia-sim-history table {
    width: 100%;
    font-size: 0.86rem;
    color: #2a3f3f;
}

.caribia-sim-history table th {
    background: #2a3f3f;
    color: #c9a449;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    padding: 10px 12px;
    border: none;
}

.caribia-sim-history table td {
    padding: 9px 12px;
    border-bottom: 1px solid #f0e6cc;
}

.caribia-sim-history table tr:nth-child(even) td {
    background: #fdf6e3;
}

.caribia-sim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 24px 28px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.07);
    border-top: 3px solid #b85c38;
    height: 380px;
    display: flex;
    flex-direction: column;
}

.caribia-sim-chart h3 {
    color: #0d6e6e;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.caribia-sim-chart canvas {
    flex: 1;
    max-height: 320px;
}

@media (max-width: 768px) {
    .caribia-sim-container { padding: 14px; }
    .caribia-sim-header { padding: 24px 22px; border-radius: 14px; }
    .caribia-sim-header h1 { font-size: 1.55rem; }
    .caribia-sim-period-bar { flex-direction: column; align-items: flex-start; gap: 8px; }
    .caribia-sim-period-right { text-align: left; }
    .caribia-sim-kpi-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
    .caribia-sim-kpi-value { font-size: 1.6rem; }
    .caribia-sim-controls { padding: 18px 18px; }
    .caribia-sim-capex-list,
    .caribia-sim-retention-list { grid-template-columns: 1fr; }
    .caribia-sim-button-row { flex-direction: column; align-items: stretch; }
    .caribia-sim-chart { height: 320px; }
}

