        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.domainState : {};
            var finalRev = ds.revenueForecast || 51.2;
            var finalEb = ds.ebitdaMargin || 22.4;
            var finalCapex = ds.capexCommitted || 0;
            var finalTurn = ds.turnover || 38;

            var revenueGap = finalRev - 55.3;
            var ebitdaGap = finalEb - 23.6;
            var capexOk = finalCapex <= 4.80 && finalCapex >= 3.5;
            var turnoverOk = finalTurn < 28;

            var greenCount = 0;
            if (finalRev >= 55.3) greenCount++;
            if (finalEb >= 23.6) greenCount++;
            if (capexOk) greenCount++;
            if (turnoverOk) greenCount++;
            if (ds.diagnosticBonus > 0.4) greenCount++;
            if (ds.channelBonus > 0.5) greenCount++;
            if (ds.segmentationBonus > 0.3) greenCount++;
            if (ds.mixBonus > 0.4) greenCount++;

            var verdict = '';
            var insights = [];
            if (greenCount >= 6 && finalRev >= 55.3 && finalEb >= 23.6) {
                verdict = 'Signed Off by Mercedes';
                insights.push('Playbook reconciles to the operating envelope.');
                insights.push('The diagnostic, channel, segmentation, and talent moves reinforce each other.');
            } else if (greenCount >= 4 && capexOk) {
                verdict = 'Signed Off with Caveat';
                insights.push('The Playbook is defensible but Mercedes flagged uneven coverage.');
                insights.push('One or two cross-round inconsistencies remain.');
            } else {
                verdict = 'Sent Back for Revision';
                insights.push('Targets missed by more than 5%; the Playbook does not reconcile.');
                if (revenueGap < -1) insights.push('Revenue forecast falls short of the $55.3M target.');
                if (ebitdaGap < -0.5) insights.push('EBITDA margin recovery is below the +120 bps target.');
                if (!capexOk) insights.push('Capex envelope misused — either over-spent or under-committed.');
                if (!turnoverOk) insights.push('Turnover remains structurally high — back-of-house wage band not inverted.');
            }

            return {
                verdict: verdict,
                forecastRevenue: finalRev,
                forecastEbitda: finalEb,
                capexCommitted: finalCapex,
                projectedTurnover: finalTurn,
                greenMetrics: greenCount,
                insights: insights
            };
        }

        getHint(state, results) {
