            var ds = state.domainState;
            if (period === 2 && (ds.diagnosticBonus || 0) < 0) return window.mySimulation.t('hint_r2_after_wrong_diagnosis');
            if (period === 3 && ds.otaTarget > 38) return window.mySimulation.t('hint_r3_ota_too_high');
            if (period === 4 && ds.gstcTier === 'full' && ds.capexSelected.indexOf('cx_energy') === -1) return window.mySimulation.t('hint_r4_gstc_inconsistent');
